以下是逐项证据，全部为代码原文（路径均相对 `/Users/jace/Documents/newapp/packages/core/core_device_native_runtime/ios/vendor/`）。

## 1. `BkFileType` 枚举完整定义

`enum BkFileType` 定义于 `BkGlassesModels.swift`，确实有 `.all`：

```142:142:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEBKGlasses/Sources/WeikeBLEBKGlasses/BkGlassesModels.swift
public enum BkFileType: Sendable { case all, picture, video, audio, music }
```

对应的协议值映射（在 `BkGlassesBleCodec.swift`）：

```213:222:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEBKGlasses/Sources/WeikeBLEBKGlasses/BkGlassesBleCodec.swift
private extension BkFileType {
    var protocolValue: UInt8 {
        switch self {
        case .all: return 0
        case .video: return 1
        case .picture: return 2
        case .audio: return 3
        case .music: return 4
        }
    }
}
```

反向解析（BLE 事件回来时把整型值映射回 `BkFileType`，`0` 或未知值 → `.all`）：

```226:235:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEBKGlasses/Sources/WeikeBLEBKGlasses/BkGlassesEventParser.swift
    private func fileType(_ value: Int) -> BkFileType {
        switch value {
        case 1: return .video
        case 2: return .picture
        case 3: return .audio
        case 4: return .music
        default: return .all
        }
    }
```

## 2. `AkFileType` 枚举完整定义

定义于 `AkGlassesModels.swift`，同样有 `.all`：

```46:46:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEAKWGlasses/Sources/WeikeBLEAKWGlasses/AkGlassesModels.swift
public enum AkFileType: Sendable { case all, picture, video, audio, music }
```

AK 没有类似 BK 的 BLE `protocolValue` 映射（AK 全程走 FTP），但 `AkNativeFtpRepository.swift` 里有 `.all` 对应的目录映射和"展开"逻辑：

```424:441:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEAKWGlasses/Sources/WeikeBLEAKWGlasses/AkNativeFtpRepository.swift
private extension Set where Element == AkFileType {
    func effectiveFileTypes() -> [AkFileType] {
        isEmpty || contains(.all) ? [.picture, .video, .audio] : Array(self)
    }
}

private extension AkFileType {
    var remoteDirectory: String {
        switch self {
        case .picture: return "/Pictures"
        case .video: return "/Videos"
        case .audio: return "/Audio"
        case .music: return "/Music"
        case .all: return "/"
        }
    }
```

## 3. `BkGlassesFileTransferService`（`BkFtpFileSyncService`）里 `queryRemoteFileCount(_:)`

真正对外提供 `files.queryRemoteFileCount` 的实现类是 `BkFtpFileSyncService`（`BkGlassesServices.swift` 里那个 `UnavailableBkFileSyncService` 只是占位符，不是真实实现）：

```52:75:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEBKGlasses/Sources/WeikeBLEBKGlasses/BkFtpFileSyncService.swift
public final class BkFtpFileSyncService: BkFileSyncService, @unchecked Sendable {
    private let network: BkNetworkSession
    private let repository: BkFtpFileRepository
    private let countProvider: BkRemoteFileCountProvider?
    private var cancelled = false

    public init(
        network: BkNetworkSession,
        repository: BkFtpFileRepository,
        countProvider: BkRemoteFileCountProvider? = nil
    ) {
        self.network = network
        self.repository = repository
        self.countProvider = countProvider
    }

    public func queryRemoteFileCount(_ type: BkFileType = .all) async throws -> Int {
        if let countProvider, type != .music {
            return try await countProvider.queryRemoteFileCount(type)
        }
        let connection = try await network.acquire(.fileSync)
        defer { Task { await network.release(.fileSync) } }
        return try await repository.listFiles(connection: connection, types: [type]).count
    }
```

关键结论：`.all != .music`，所以走 `countProvider`（真实实例是 `DefaultBkBleFileCountProvider`），**不会**触碰 FTP/AP。`countProvider.queryRemoteFileCount` 实现：

```1:36:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEBKGlasses/Sources/WeikeBLEBKGlasses/BkBleFileCountProvider.swift
import Foundation

public struct DefaultBkBleFileCountProvider: BkRemoteFileCountProvider {
    private let rawDataStream: @Sendable () -> AsyncStream<Data>
    private let parser: BkGlassesEventParser
    private let queryTimeout: TimeInterval
    private let rawWriter: @Sendable (Data) async throws -> Void

    public init(
        rawDataStream: @escaping @Sendable () -> AsyncStream<Data> = { AsyncStream { $0.finish() } },
        parser: BkGlassesEventParser = BkGlassesEventParser(),
        queryTimeout: TimeInterval = 5,
        rawWriter: @escaping @Sendable (Data) async throws -> Void
    ) {
        self.rawDataStream = rawDataStream
        self.parser = parser
        self.queryTimeout = queryTimeout
        self.rawWriter = rawWriter
    }

    public func queryRemoteFileCount(_ type: BkFileType) async throws -> Int {
        async let response: Int = bkWithTimeout(seconds: queryTimeout) {
            for await data in rawDataStream() {
                for event in parser.parse(data) {
                    if case let .remoteFileCountChanged(responseType, count) = event,
                       responseType == type {
                        return count
                    }
                }
            }
            throw BkGlassesProviderError.failed(.bluetoothNotConnected, "BLE disconnected while waiting for BK file count")
        }
        try await rawWriter(BkGlassesBleCodec.queryFileCount(type))
        return try await response
    }
}
```

而 `BkGlassesBleCodec.queryFileCount(type)` 就是单个 BLE 帧，直接把 `type.protocolValue`（`.all` → `0`）塞进 payload 发出去：

```49:51:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEBKGlasses/Sources/WeikeBLEBKGlasses/BkGlassesBleCodec.swift
    public static func queryFileCount(_ type: BkFileType) -> Data {
        frame(dest: destNormal, cmd: cmdGlasses, subCmd: glassesSyncFileCount, payload: [type.protocolValue])
    }
```

**结论：BK 传 `.all` 时，是一次性发单个 BLE 协议帧（`glassesSyncFileCount` 子命令 + payload `[0]`），等待固件回一次 `remoteFileCountChanged(type: .all, count:)` 事件，不是内部循环三次分别查询再求和。**（只有传 `.music` 时才会绕过 `countProvider`，走 FTP `listFiles` 目录枚举。）

## 4. `AkGlassesFileTransferService`（`AkFtpFileSyncService`）里 `queryRemoteFileCount(_:)`

AK 没有 BLE 计数 provider（vendor 目录下没有 `AkBleFileCountProvider` 之类文件），唯一实现是纯 FTP：

```48:68:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEAKWGlasses/Sources/WeikeBLEAKWGlasses/AkFtpFileSyncService.swift
public final class AkFtpFileSyncService: AkFileSyncService, @unchecked Sendable {
    private let network: AkNetworkSession
    private let repository: AkFtpFileRepository
    private let retryNetworkRecoveryOnFailure: Bool
    private var cancelled = false

    public init(
        network: AkNetworkSession,
        repository: AkFtpFileRepository,
        retryNetworkRecoveryOnFailure: Bool = false
    ) {
        self.network = network
        self.repository = repository
        self.retryNetworkRecoveryOnFailure = retryNetworkRecoveryOnFailure
    }

    public func queryRemoteFileCount(_ type: AkFileType = .all) async throws -> Int {
        let connection = try await network.acquire(.fileSync)
        defer { Task { await network.release(.fileSync) } }
        return try await repository.listFiles(connection: connection, types: [type]).count
    }
```

`repository.listFiles` 的真实实现（`AkNativeFtpRepository`），这里就是"内部循环三次目录再求和"发生的地方——`types.effectiveFileTypes()` 把 `[.all]` 展开成 `[.picture, .video, .audio]`，逐个目录 `client.list(dir)` 枚举再拼接数组：

```29:44:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEAKWGlasses/Sources/WeikeBLEAKWGlasses/AkNativeFtpRepository.swift
    public func listFiles(connection: AkNetworkConnection, types: Set<AkFileType>) async throws -> [AkRemoteFile] {
        try await Task.detached(priority: nil) { [credentials] in
            let client = try FtpClient(host: connection.ip, credentials: credentials)
            defer { client.close() }
            var files: [AkRemoteFile] = []
            for type in types.effectiveFileTypes() {
                let dir = type.remoteDirectory
                for entry in try client.list(dir) where type.matches(entry.name) {
                    files.append(AkRemoteFile(
                        path: "\(dir)/\(entry.name)",
                        name: entry.name,
                        type: type,
                        sizeBytes: entry.sizeBytes
                    ))
                }
            }
            return files
        }.value
    }
```

**结论：AK 传 `.all` 时，全程走 FTP `listFiles()` 目录枚举，且内部确实会对 `/Pictures`、`/Videos`、`/Audio` 三个目录分别 `client.list()`，再把三份结果数组拼起来，`.count` 就是三者之和——没有"一次性查全部"的协议帧。**

**AP session 协商发生的位置**：`queryRemoteFileCount` 第一步 `try await network.acquire(.fileSync)`——这一步才真正触发 AP 协商，而不是在拿到 `session.akwGlasses(config:)` 的 controller 时就触发。证据链：

- `akwGlasses(config:)` 构造阶段只是把 `network` 对象 new 出来，没有任何 I/O：

```125:145:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEAKWGlasses/Sources/WeikeBLEAKWGlasses/AkGlassesServices.swift
public extension WearfitBLESession {
    func akwGlasses(config: AkGlassesConfig = AkGlassesConfig()) async -> AkGlassesDevice {
```
（此方法体内 `let network = config.networkSessionFactory(runtime, identity)` 只是调用工厂闭包实例化 `IosAkApNetworkSession`，未调用 `acquire`。）

- 真正的 AP 打开逻辑在 `IosAkApNetworkSession.acquire(_:)`，它转发给 `lease.acquire(use)`，由 `IosAkApNetworkOpener.open()` 发送开热点 BLE 命令、等待 `hotspotOpened` 事件、再 Wi-Fi join：

```118:121:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEAKWGlasses/Sources/WeikeBLEAKWGlasses/AkIosApNetworkSession.swift
    public func acquire(_ use: AkNetworkUse) async throws -> AkNetworkConnection {
        debugLog?("AKW AP acquire use=\(use)")
        return try await lease.acquire(use)
    }
```

```147:187:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEAKWGlasses/Sources/WeikeBLEAKWGlasses/AkIosApNetworkSession.swift
    func open() async throws -> AkNetworkConnection {
        debugLog?("AKW AP open begin use=\(use) reason=\(use.wifiApOpenReasonLog) commandTimeout=\(options.openCommandTimeout)s ssidTimeout=\(options.hotspotSSIDTimeout)s joinTimeout=\(options.hotspotJoinTimeout)s fallbackDeviceIP=\(options.fallbackDeviceIp)")
