```

即：`acquire(.fileSync)` 才是链路上真正触发"发 33 04 开热点命令 → 等 hotspotOpened 事件 → Wi-Fi join"的那一步，`queryRemoteFileCount`/`startSync`/`listFiles` 都是通过它间接触发；拿到 controller/device 对象本身不产生任何网络副作用。

## 5. `iosApConfig()` 完整实现

`AkGlassesControllers.iosApConfig()`（**没有** `networkModeOverride` 字段可设——因为 `AkGlassesConfig` 结构体本身就没有这个属性，AK 只有 AP 一种网络模式）：

```18:63:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEAKWGlasses/Sources/WeikeBLEAKWGlasses/AkGlassesControllers.swift
    public static func iosApConfig(
        options: IosAkNetworkOptions = IosAkNetworkOptions(),
        ftpCredentials: AkFtpCredentials = AkFtpCredentials(),
        otaOptions: AkOtaOptions = AkOtaOptions(),
        otaZipExpander: AkFirmwareZipExpander? = nil,
        debugLog: IosAkApNetworkSession.LogHandler? = nil
    ) -> AkGlassesConfig {
        let parser = AkGlassesEventParser()
        return AkGlassesConfig(
            eventParser: parser,
            networkSessionFactory: { runtime, _ in
                IosAkApNetworkSession(
                    rawDataStream: runtime.rawDataStream(),
                    parser: parser,
                    options: options,
                    rawWriter: runtime.rawWriter,
                    wifiApOpenCommandWriter: { use in
                        try await runtime.session.device.openWifiAp(reason: use.wifiApOpenReason)
                    },
                    wifiApCloseCommandWriter: {
                        try await runtime.session.device.closeWifiAp()
                    },
                    debugLog: debugLog
                )
            },
            fileSyncServiceFactory: { _, _, network in
                AkFtpFileSyncService(
                    network: network,
                    repository: AkNativeFtpRepository(credentials: ftpCredentials),
                    retryNetworkRecoveryOnFailure: true
                )
            },
            otaServiceFactory: { runtime, _, network in
                DefaultAkOtaService(
                    network: network,
                    batteryProvider: { nil },
                    uploader: AkNativeFtpRepository(credentials: ftpCredentials),
                    zipExpander: otaZipExpander,
                    options: otaOptions,
                    rawDataStream: runtime.rawDataStream(),
                    parser: parser,
                    rawWriter: runtime.rawWriter
                )
            }
        )
    }
```

`BkGlassesControllers.iosApConfig()`（**显式设置 `networkModeOverride: .ap`**，强制走 AP 模式；与 `iosStationTcpConfig()` 里的 `networkModeOverride: .stationTcp` 对照即可看出这是切换网络模式的开关）：

```107:168:packages/core/core_device_native_runtime/ios/vendor/WeikeBLEBKGlasses/Sources/WeikeBLEBKGlasses/BkGlassesControllers.swift
    public static func iosApConfig(
        provider: IosBkSmartCameraProvider = UnavailableIosBkSmartCameraProvider(),
        options: IosBkNetworkOptions = IosBkNetworkOptions(),
        previewOptions: BkPreviewOptions = BkPreviewOptions(),
        ftpCredentials: BkFtpCredentials = BkFtpCredentials(),
        firmwareExpander: BkFirmwarePackageExpander = DefaultBkFirmwarePackageExpander(),
        postUpdateCoordinator: BkOtaPostUpdateCoordinator = BkStandardOtaPostUpdateCoordinator()
    ) -> BkGlassesConfig {
        let parser = BkGlassesEventParser()
        return BkGlassesConfig(
            eventParser: parser,
            networkModeOverride: .ap,
            networkSessionFactory: { runtime, _ in
                IosBkApNetworkSession(
                    rawDataStream: runtime.rawDataStream,
                    parser: parser,
                    options: options,
                    rawWriter: runtime.rawWriter,
                    wifiApCommandWriter: { enabled in
                        if enabled {
                            try await runtime.session.device.openWifiAp()
                        } else {
                            try await runtime.session.device.closeWifiAp()
                        }
                    }
                )
            },
            cameraSessionFactory: { _, identity, network in
                IosBkCameraSession(
                    identity: identity,
                    network: network,
                    provider: provider,
                    options: previewOptions
                )
            },
            fileSyncServiceFactory: { runtime, _, network in
                BkFtpFileSyncService(
                    network: network,
                    repository: BkNativeFtpRepository(credentials: ftpCredentials),
                    countProvider: DefaultBkBleFileCountProvider(
                        rawDataStream: runtime.rawDataStream,
                        parser: parser,
                        rawWriter: runtime.rawWriter
                    )
                )
            },
            otaServiceFactory: { runtime, identity, network in
                DefaultBkOtaService(
                    identity: identity,
                    session: runtime.session,
                    network: network,
                    batteryProvider: { nil },
                    uploader: BkNativeFtpRepository(credentials: ftpCredentials),
                    firmwareExpander: firmwareExpander,
                    postUpdateCoordinator: postUpdateCoordinator,
                    rawDataStream: runtime.rawDataStream(),
                    parser: parser,
                    rawWriter: runtime.rawWriter
                )
            }
        )
    }
```

一个附带发现：这个仓库里的 BSD `grep -r` 在这两个目录下会静默返回"无匹配"（不报错、exit code 1），即便目标字符串确实存在于文件里；直接对单文件 `grep` 或用 `find ... -print0 | xargs -0 grep` 都能正常命中。所以本次排查全部改用 `find + xargs grep` 完成，供你之后在这两个 vendor 目录里排查时注意，避免被"没找到"误导。
